var s=[{title:`Три категорії`,text:`Робота проти розгинання не дає попереку надто прогинатися, як у планці чи вправі «мертвий жук». Робота проти обертання протидіє скручуванню, як у жимі Паллофа із безпечно закріпленим еспандером. Робота проти бічного згинання протидіє нахилу вбік, як у бічній планці чи перенесенні валізи. Черевна стінка, м’язи хребта, діафрагма та стегна: усе це допомагає контролювати тулуб.`},{title:`Приклади техніки`,text:`У планці на передпліччях вирівняйте ребра й таз, відштовхуйте підлогу руками і продовжуйте дихати, утримуючи положення. У вправі «мертвий жук» рухайте протилежні руку й ногу лише настільки, наскільки тулуб лишається під контролем. У бічній планці тримайте пряму лінію з опорою і не дозволяйте стегнам опускатися.`},{title:`Прогресії`,text:`Почніть із коротких утримань і коротких важелів. Бічна планка з опорою на коліно може передувати повній бічній планці, а «мертвий жук» зі зігнутими колінами: витягуванню прямих ніг. Ускладнюйте, подовжуючи важіль, додаючи помірне навантаження чи утримуючи довше під контролем. Якщо постава ламається, вправа стала надто складною. Стежте за диханням і вирівнюванням у міру прогресу.`},{title:`Окрім планок`,text:`Скручування та інші вправи на згинання тулуба також тренують прес, але не покривають усіх завдань кору. Тяги, присіди та перенесення вантажу також змушують тулуб працювати для стабільності. Вам не потрібно тренувати кожен напрямок в одному занятті. Включайте кілька контрольованих вправ на кор протягом тижня, обраних відповідно до вашого досвіду й того, як їх переносить поперек. Важливіше виконувати їх регулярно і прогресувати в темпі, який ви переносите.`}];var i=[{label:`Бібліотека вправ ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: безпека та основи силових тренувань`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var l={sections:s,sources:i};export{l as default,s as sections,i as sources};